<main class="content-shell"><div class="page-heading"><div><p class="section-kicker">Decisões administrativas</p><h1>Despachos</h1><p class="muted">Consulte as decisões associadas aos expedientes.</p></div></div><?php if ($message): ?><div class="flash <?= htmlspecialchars($message['type'], ENT_QUOTES, 'UTF-8') ?>" role="status"><?= htmlspecialchars($message['message'], ENT_QUOTES, 'UTF-8') ?></div><?php endif; ?><form class="search-bar" method="get" action="despachos.php"><label for="search">Pesquisar por número, assunto, conteúdo ou decisão</label><div><input id="search" name="search" type="search" value="<?= htmlspecialchars($search, ENT_QUOTES, 'UTF-8') ?>" placeholder="Ex.: EXP-2026-001"><button type="submit">Pesquisar</button></div></form><section class="table-panel"><div class="panel-heading"><h2>Despachos registados</h2><span><?= count($dispatches) ?> resultado(s)</span></div><div class="table-wrap"><table><thead><tr><th>Expediente</th><th>Conteúdo</th><th>Decisão</th><th>Responsável</th><th>Estado</th><th>Data</th><th>Ação</th></tr></thead><tbody><?php foreach ($dispatches as $dispatch): ?><tr><td><strong><?= htmlspecialchars($dispatch['reference_code'], ENT_QUOTES, 'UTF-8') ?></strong><br><span class="table-secondary"><?= htmlspecialchars($dispatch['subject'], ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars(mb_strimwidth($dispatch['content'], 0, 80, '...'), ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($dispatch['decision'] ?: 'Sem decisão', ENT_QUOTES, 'UTF-8') ?></td><td><?= htmlspecialchars($dispatch['author_name'] ?? 'Utilizador removido', ENT_QUOTES, 'UTF-8') ?></td><td><span class="state-badge state-dispatch-<?= htmlspecialchars($dispatch['status'], ENT_QUOTES, 'UTF-8') ?>"><?= htmlspecialchars($statuses[$dispatch['status']] ?? $dispatch['status'], ENT_QUOTES, 'UTF-8') ?></span></td><td><?= htmlspecialchars(date('d/m/Y H:i', strtotime($dispatch['created_at'])), ENT_QUOTES, 'UTF-8') ?></td><td><a class="table-link" href="despacho-view.php?id=<?= (int) $dispatch['id'] ?>">Ver</a></td></tr><?php endforeach; ?><?php if (!$dispatches): ?><tr><td colspan="7" class="empty-state">Nenhum despacho encontrado.</td></tr><?php endif; ?></tbody></table></div></section></main></body></html>